package org.opensmartisanos.ui.widget;
import android.content.Context;import android.graphics.Bitmap;import android.graphics.Canvas;import android.graphics.Paint;import android.graphics.PorterDuff;import android.graphics.PorterDuffXfermode;import android.graphics.Rect;import android.graphics.drawable.BitmapDrawable;import android.graphics.drawable.Drawable;import android.util.AttributeSet;import android.view.View;import org.opensmartisanos.ui.R;
public class SmartisanCircleProgressView extends View {private final Drawable circle;private final Bitmap mask;private final Paint paint=new Paint();private final Rect rect;private final int size;private float sweep;public SmartisanCircleProgressView(Context c){this(c,null);}public SmartisanCircleProgressView(Context c,AttributeSet a){super(c,a);circle=getResources().getDrawable(R.drawable.smartisan_rom_circle);mask=((BitmapDrawable)getResources().getDrawable(R.drawable.smartisan_rom_circle_mask)).getBitmap();size=getResources().getDimensionPixelSize(R.dimen.smartisan_rom_circle_progress_view_size);rect=new Rect(0,0,size,size);paint.setColor(getResources().getColor(R.color.smartisan_rom_circle_progress_view_arc_color));}@Override protected void onMeasure(int w,int h){setMeasuredDimension(size,size);}@Override protected void onDraw(Canvas c){int layer=c.saveLayer(0,0,size,size,null);c.drawArc(0,0,size,size,-90,sweep,true,paint);paint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_IN));c.drawBitmap(mask,null,rect,paint);paint.setXfermode(null);c.restoreToCount(layer);circle.setBounds(rect);circle.draw(c);}public int getCircleWidth(){return size;}public int getCircleHeight(){return size;}public float getSweepAngle(){return sweep;}public void setSweepAngle(float value){sweep=value;invalidate();}public void reset(){setSweepAngle(0);}}
